import functools
from typing import ForwardRef, Union, List, Any, Dict
from fastapi import FastAPI
from fastapi.routing import APIRoute

# Define a class for forward reference
class User:
    pass

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

app = FastAPI()

@app.get("/")
@wrapper
def read_root(user: "User") -> str:
    return "Hello"

def test_wrapped_method_type_inference():
    # This should trigger the NameError if the bug is present
    # because get_typed_signature will be called during route registration
    # but we already registered it above.
    # Let's try to manually trigger the dependant creation.
    from fastapi.dependencies.utils import get_dependant

    # The endpoint is the wrapped function
    endpoint = read_root

    try:
        get_dependant(path="/", call=endpoint)
        print("Success!")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
        raise e
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_method_type_inference()

